# Figure 4 (GALNT score "GIScore" in PAAD), layout follows the template Fig 4 (Fig4_template.png):
# A forest table | B model C-index table | C1-C3 diagnostics | D KM (train) | E-G KM (validation) | H-J donut tables | K Reactome | L immune proxy | M MDSC scatter
suppressPackageStartupMessages({library(data.table); library(ggplot2); library(patchwork); library(scales); library(survival); library(ggforce); library(ggExtra); library(randomForestSRC); library(CoxBoost)})
root <- "${PROJECT_ROOT}"; r4 <- file.path(root, "04_results/2026-10-12_Figure4_GALNT_run01"); out <- file.path(root, "05_figures/2026-10-12_Figure4_GALNT_run01"); dir.create(out, recursive = TRUE, showWarnings = FALSE)
fam <- "Arial"; bs <- 6; cLow <- "#E3B23C"; cHigh <- "#4C7FB8"; pp <- .pt
theme_pub <- function(bs = 6) theme_classic(base_size = bs, base_family = fam) + theme(axis.line = element_line(linewidth = 0.25), axis.ticks = element_line(linewidth = 0.25), plot.title = element_text(size = bs + 0.5, face = "bold"), legend.key.size = unit(2.6, "mm"), legend.title = element_text(size = bs), legend.text = element_text(size = bs - 0.5), plot.margin = margin(2, 3, 2, 2))
pfmt <- function(p) vapply(p, function(x) if (x < 0.001) formatC(x, format = "e", digits = 1) else formatC(x, format = "f", digits = if (x < 0.01) 4 else 3), "")
fz <- readRDS(file.path(r4, "FROZEN_model.rds")); A <- fread(file.path(r4, "A_univariate_cox_training.csv")); sm <- fread(file.path(r4, "validation_summary.csv")); am <- fread(file.path(r4, "B_all_models_cindex.csv"))
sc <- rbind(fread(file.path(r4, "training_scores.csv"))[, .(cohort, time, event, risk, group)], fread(file.path(r4, "validation_scores.csv"))[, .(cohort, time, event, risk, group)])
sel_genes <- fz$model$genes; cf <- coef(fz$model$fit); cfd <- data.table(gene = sel_genes, beta = as.numeric(cf[match(sel_genes, fz$model$fit$xnames)])); cfd <- cfd[order(-abs(beta))]; frm <- paste(sprintf("%+.2f\u00b7z(%s)", cfd$beta, cfd$gene), collapse = " ")
## ---------- A: forest table ----------
A[, grp := ifelse(HR > 1, "risk", "prot")]; A <- rbind(A[grp == "risk"][order(-HR)], A[grp == "prot"][order(-HR)]); A[, y := rev(seq_len(.N))]; nA <- nrow(A)
A[, `:=`(ptxt = formatC(p, format = "f", digits = 3), hrtxt = sprintf("%.3f", HR), citxt = sprintf("%.3f - %.3f", lo, hi))]; A[p < 0.001, ptxt := "< 0.001"]
bgc <- c(risk = "#FBF0D0", prot = "#D8EEE2"); hdr_y <- nA + 1
pAt <- ggplot(A) + geom_rect(aes(xmin = 0, xmax = 4, ymin = y - 0.5, ymax = y + 0.5, fill = grp)) + scale_fill_manual(values = bgc, guide = "none") + annotate("rect", xmin = 0, xmax = 4, ymin = hdr_y - 0.5, ymax = hdr_y + 0.5, fill = "#9CC3DA") +
  geom_text(aes(x = 0.1, y = y, label = gene, fontface = ifelse(gene %in% sel_genes, "bold", "plain")), hjust = 0, size = 5 / pp, family = fam) + geom_text(aes(x = 1.45, y = y, label = ptxt), hjust = 0.5, size = 5 / pp, family = fam) + geom_text(aes(x = 2.15, y = y, label = hrtxt), hjust = 0.5, size = 5 / pp, family = fam) + geom_text(aes(x = 3.2, y = y, label = citxt), hjust = 0.5, size = 5 / pp, family = fam) +
  annotate("text", x = c(0.1, 1.45, 2.15, 3.2), y = hdr_y, label = c("Gene", "p-value", "HR", "95% CI"), hjust = c(0, 0.5, 0.5, 0.5), size = 5.4 / pp, family = fam, fontface = "bold") + coord_cartesian(xlim = c(0, 4), ylim = c(0.5, hdr_y + 0.5), expand = FALSE) + theme_void() + theme(plot.margin = margin(2, 0, 14, 2))
pAf <- ggplot(A, aes(HR, y)) + geom_rect(aes(xmin = 0.4, xmax = 2.2, ymin = y - 0.5, ymax = y + 0.5, fill = grp), inherit.aes = FALSE) + annotate("rect", xmin = 0.4, xmax = 2.2, ymin = hdr_y - 0.5, ymax = hdr_y + 0.5, fill = "#9CC3DA") + scale_fill_manual(values = bgc, guide = "none") + geom_vline(xintercept = 1, linewidth = 0.3) +
  geom_errorbar(aes(xmin = lo, xmax = hi), width = 0.3, orientation = "y", linewidth = 0.3, colour = "#3B6FB0") + geom_point(shape = 18, size = 1.9, colour = "#D9453B") + scale_x_log10(breaks = c(0.5, 1, 2), labels = c("0.5", "1", "2")) + coord_cartesian(xlim = c(0.4, 2.2), ylim = c(0.5, hdr_y + 0.5), expand = FALSE) + labs(x = "Hazard ratio") + theme_pub() + theme(axis.line.y = element_blank(), axis.text.y = element_blank(), axis.ticks.y = element_blank(), axis.title.y = element_blank(), plot.margin = margin(2, 3, 2, 0))
pA <- wrap_plots(pAt + labs(tag = "A"), pAf, nrow = 1, widths = c(1.55, 1))
## ---------- B: model C-index table ----------
cohs <- c("TCGA-CV", "GSE62452", "GSE57495", "GSE85916"); labs_c <- c("TCGA\n(CV)", "GSE62452", "GSE57495", "GSE85916"); ccol <- c("#9CC9E6", "#3F7FBF", "#8FD08F", "#E3B23C")
w <- dcast(am, model ~ cohort, value.var = "cindex"); w[, mean := rowMeans(.SD), .SDcols = cohs]; w <- w[order(-`TCGA-CV`, -mean)]; w[, y := rev(seq_len(.N))]; nB <- nrow(w)
bt <- melt(w, id.vars = c("model", "y"), measure.vars = cohs, variable.name = "cohort", value.name = "cindex"); bt[, x := match(cohort, cohs)]
pB <- ggplot() + geom_tile(data = bt, aes(x, y, fill = cindex), colour = "white", linewidth = 0.3, width = 0.96, height = 0.96) + geom_text(data = bt, aes(x, y, label = sprintf("%.3f", cindex)), size = 4.6 / pp, family = fam) +
  geom_tile(data = bt[model == fz$selected], aes(x, y), fill = NA, colour = "black", linewidth = 0.45, width = 0.96, height = 0.96) +
  geom_tile(data = data.frame(x = 1:4, y = nB + 1), aes(x, y), fill = ccol, height = 0.96, width = 0.96) + annotate("text", x = 1:4, y = nB + 1, label = labs_c, size = 4.4 / pp, family = fam, colour = "black", lineheight = 0.8) +
  geom_rect(data = w, aes(xmin = 4.75, xmax = 4.75 + 1.2 * (mean - 0.45) / 0.2, ymin = y - 0.38, ymax = y + 0.38), fill = "#4A8AC4") + geom_text(data = w, aes(x = 4.8, y = y, label = sprintf("%.3f", mean)), hjust = 0, size = 4.6 / pp, family = fam, colour = "white") + annotate("text", x = 5.35, y = nB + 1, label = "Mean", size = 5 / pp, family = fam, fontface = "bold") +
  scale_y_continuous(breaks = w$y, labels = w$model, expand = expansion(add = c(0.5, 0.6))) + scale_x_continuous(expand = expansion(add = c(0.5, 0.1))) + scale_fill_gradientn(colours = c("#4DB5A0", "#BFE3D6", "#F6EBC0", "#E5A93C"), limits = c(0.45, 0.66), oob = squish, name = "C-index", breaks = c(0.5, 0.6)) +
  labs(x = NULL, y = NULL, subtitle = paste0("Selected (box): ", fz$selected, "; training CV only. Score = ", frm)) + theme_pub() +
  theme(axis.line = element_blank(), axis.ticks = element_blank(), axis.text.x = element_blank(), axis.text.y = element_text(size = 5.2), plot.subtitle = element_text(size = 4.8, family = fam, hjust = 0), legend.position = "right", legend.key.width = unit(2.5, "mm"), legend.key.height = unit(7, "mm"), plot.margin = margin(2, 2, 2, 2))
## ---------- C1-C3: diagnostics (Lasso and RSF on all 19 candidates) ----------
cv <- fz$diag$lasso$cv; ld <- data.frame(l = log(cv$lambda), m = cv$cvm, lo = cv$cvlo, hi = cv$cvup, nz = cv$nzero); bx <- seq(ceiling(min(ld$l)), floor(max(ld$l)), length.out = 7); bx <- ld$l[sapply(bx, function(b) which.min(abs(ld$l - b)))]
pC1 <- ggplot(ld, aes(l, m)) + geom_errorbar(aes(ymin = lo, ymax = hi), width = 0.03, linewidth = 0.2, colour = "grey60") + geom_point(colour = "#D9453B", size = 0.6) + geom_vline(xintercept = log(c(cv$lambda.min, cv$lambda.1se)), linetype = 2, linewidth = 0.25) +
  scale_x_continuous(sec.axis = sec_axis(~., breaks = bx, labels = ld$nz[match(bx, ld$l)])) + labs(x = expression(Log(lambda)), y = "Partial likelihood deviance") + theme_pub() + theme(axis.text.x.top = element_text(size = 4.8), panel.border = element_rect(fill = NA, linewidth = 0.25), axis.line = element_blank())
er <- fz$diag$rsf$fit$err.rate; er <- data.frame(n = seq_along(er), e = as.numeric(er)); er <- er[is.finite(er$e), ]
pC2 <- ggplot(er, aes(n, e)) + geom_line(colour = "#3B6FB0", linewidth = 0.4) + labs(x = "Number of trees", y = "Error rate") + theme_pub() + theme(panel.border = element_rect(fill = NA, linewidth = 0.25), axis.line = element_blank())
vi <- fz$diag$rsf$fit$importance; vd <- data.frame(g = names(vi), v = as.numeric(vi)); vd <- head(vd[order(-vd$v), ], 15); vd$g <- factor(vd$g, levels = rev(vd$g))
pC3 <- ggplot(vd, aes(v, g, fill = v)) + geom_col(width = 0.85) + scale_fill_gradient(low = "#D9C5EA", high = "#6A3D93", guide = "none") + labs(x = "Variable importance (RSF)", y = NULL) + theme_pub() + theme(axis.text.y = element_text(size = 5))
pC <- wrap_plots(pC1 + labs(tag = "C"), pC2, pC3, nrow = 1, widths = c(1.15, 1, 0.95))
## ---------- D-G: Kaplan-Meier ----------
stepify <- function(k) { k <- k[order(k$time), ]; data.frame(time = c(k$time[1], rep(k$time[-1], each = 2)), lo = rep(k$lo, each = 2)[seq_len(2 * nrow(k) - 1)], hi = rep(k$hi, each = 2)[seq_len(2 * nrow(k) - 1)]) }
km <- function(co, ttl, tagid = NULL) { d <- as.data.frame(sc[cohort == co]); d$g <- factor(d$group, levels = c("Low", "High")); f <- survfit(Surv(time, event) ~ g, d); s <- summary(f, censored = TRUE); k <- data.frame(time = s$time, surv = s$surv, lo = s$lower, hi = s$upper, g = sub("g=", "", s$strata), cens = s$n.censor)
  k <- rbind(data.frame(time = 0, surv = 1, lo = 1, hi = 1, g = "Low", cens = 0), data.frame(time = 0, surv = 1, lo = 1, hi = 1, g = "High", cens = 0), k); k$g <- factor(k$g, levels = c("Low", "High")); r <- sm[cohort == co]; lim <- min(ceiling(max(d$time) / 24) * 24, 120); nl <- sum(d$g == "Low"); nh <- sum(d$g == "High")
  rb <- rbindlist(lapply(levels(k$g), function(gg) { z <- stepify(k[k$g == gg, ]); z$g <- gg; z })); rb$g <- factor(rb$g, levels = c("Low", "High"))
  ggplot() + geom_step(data = k, aes(time, surv, colour = g), linewidth = 0.4) + geom_point(data = k[k$cens > 0, ], aes(time, surv, colour = g), shape = 3, size = 0.55, stroke = 0.2) +
    scale_colour_manual(values = c(Low = cLow, High = cHigh), labels = c(sprintf("GIScore-low (n=%d)", nl), sprintf("GIScore-high (n=%d)", nh)), name = NULL) + scale_fill_manual(values = c(Low = cLow, High = cHigh), guide = "none") + scale_x_continuous(breaks = seq(0, 120, 24)) +
    annotate("text", x = lim * 0.02, y = 0.05, hjust = 0, vjust = 0, size = 5 / pp, family = fam, lineheight = 1.05, label = sprintf("%s\nHR = %.2f\np = %s", ttl, r$HR_high_vs_low, pfmt(r$logrank_p))) + coord_cartesian(xlim = c(0, lim), ylim = c(0, 1)) + labs(x = "Time in months", y = "Overall Survival") +
    theme_pub() + theme(legend.position = c(0.99, 0.99), legend.justification = c(1, 1), legend.background = element_blank(), legend.key.height = unit(2.2, "mm"), legend.key.width = unit(5, "mm"), legend.text = element_text(size = 5), legend.spacing.y = unit(0, "mm"))
}
pD <- km("TCGA-PAAD", "TCGA-PAAD (OS)"); pE <- km("GSE62452", "GSE62452 (OS)"); pF <- km("GSE57495", "GSE57495 (OS)"); pG <- km("GSE85916", "GSE85916 (OS)")
## ---------- H-J: donut tables ----------
cols <- c("\u2264 65 years" = "#86CBD6", "> 65 years" = "#3AA0B3", "Female" = "#8ED0AE", "Male" = "#2C9A78", "Alive" = "#AEB9DA", "Dead" = "#3A4A92", "Stage I/II" = "#F0A398", "Stage III/IV" = "#DD4A3D", "Grade 1/2" = "#F3D6A8", "Grade 3/4" = "#E99E3A")
tcga <- fread(file.path(r4, "H_clinical_table_TCGA_samples.csv")); tcga[, `:=`(Age = ifelse(ageg == "<=65", "\u2264 65 years", "> 65 years"), Gender = ifelse(sexg == "FEMALE", "Female", "Male"), Stage = ifelse(stageg == "Stage I-II", "Stage I/II", ifelse(stageg == "Stage III-IV", "Stage III/IV", NA)), Grade = ifelse(gradeg == "G1-2", "Grade 1/2", ifelse(gradeg == "G3-4", "Grade 3/4", NA)), OS.event = ifelse(event == 1, "Dead", "Alive"))]
vs <- fread(file.path(r4, "validation_scores.csv")); v62 <- vs[cohort == "GSE62452"]; v62[, `:=`(Stage = ifelse(grepl("^III|^IV", stage), "Stage III/IV", "Stage I/II"), Grade = ifelse(grade %in% c("G1", "G2"), "Grade 1/2", ifelse(grade %in% c("G3", "G4"), "Grade 3/4", NA)), OS.event = ifelse(event == 1, "Dead", "Alive"))]
v57 <- vs[cohort == "GSE57495"]; v57[, `:=`(Stage = ifelse(grepl("^2", stage), "Stage II", "Stage I"), OS.event = ifelse(event == 1, "Dead", "Alive"))]
cols <- c(cols, "Stage I" = "#F0A398", "Stage II" = "#DD4A3D")
donut <- function(d, vars, title, tagid = NULL) { d <- as.data.frame(d); lw <- 1.35; wd <- (6.2 - lw) / length(vars); xs <- lw + wd * (seq_along(vars) - 0.5); rows <- c(High = 2.1, Low = 0.9); parts <- list(); pv <- numeric(0)
  for (i in seq_along(vars)) { v <- vars[i]; x <- d[!is.na(d[[v]]), ]; t <- table(factor(x$group, c("High", "Low")), x[[v]]); pv[i] <- tryCatch(fisher.test(t)$p.value, error = function(e) NA); for (g in c("High", "Low")) for (l in colnames(t)) parts[[length(parts) + 1]] <- data.frame(x0 = xs[i], y0 = rows[g], lev = l, n = t[g, l]) }
  P <- do.call(rbind, parts); P$lev <- factor(P$lev, levels = names(cols)); n_h <- sum(d$group == "High"); n_l <- sum(d$group == "Low")
  ggplot() + geom_arc_bar(data = P, aes(x0 = x0, y0 = y0, r0 = 0.2, r = 0.46, amount = n, fill = lev), stat = "pie", colour = "white", linewidth = 0.15) + scale_fill_manual(values = cols, guide = "none") +
    annotate("text", x = lw / 2, y = c(2.1, 0.9), label = c(sprintf("High\n(n=%d)", n_h), sprintf("Low\n(n=%d)", n_l)), size = 4.6 / pp, family = fam, lineheight = 0.95) + annotate("text", x = lw / 2, y = 3.05, label = "GIScore", size = 4.4 / pp, family = fam, fontface = "bold") + annotate("text", x = xs, y = 3.05, label = vars, size = 4.4 / pp, family = fam, fontface = "bold") +
    annotate("text", x = lw / 2, y = 0.1, label = "Fisher p", size = 4.4 / pp, family = fam) + annotate("text", x = xs, y = 0.1, label = ifelse(pv < 0.001, "<0.001", formatC(pv, format = "f", digits = 3)), size = 4.6 / pp, family = fam) +
    annotate("rect", xmin = c(0, lw + wd * (seq_along(vars) - 1)) + 0.03, xmax = c(lw, lw + wd * seq_along(vars)) - 0.03, ymin = 2.7, ymax = 3.4, fill = NA, colour = "grey55", linewidth = 0.25) + annotate("segment", x = 0.03, xend = 6.17, y = c(1.5, 0.35), yend = c(1.5, 0.35), colour = "grey85", linewidth = 0.2) +
    labs(title = title) + coord_fixed(xlim = c(0, 6.2), ylim = c(-0.05, 3.45), expand = FALSE) + theme_void(base_family = fam) + theme(plot.title = element_text(size = 6.5, face = "bold", hjust = 0.5, margin = margin(0, 0, 1, 0)), plot.margin = margin(1, 1, 1, 1)) }
pH <- donut(tcga, c("Age", "Stage", "Gender", "Grade", "OS.event"), "TCGA-PAAD"); pI <- donut(v62, c("Stage", "Grade", "OS.event"), "GSE62452"); pJ <- donut(v57, c("Stage", "OS.event"), "GSE57495")
lg <- data.frame(lab = names(cols)[1:10], col = 1:2, row = c(3, 3, 2, 2, 1, 1, 0, 0, -1, -1)); lg$x <- c(0.02, 0.5)[lg$col]; lg$fill <- cols[lg$lab]
pLg <- ggplot(lg) + geom_tile(aes(x, row, fill = lab), width = 0.06, height = 0.55) + geom_text(aes(x + 0.045, row, label = lab), hjust = 0, size = 4.8 / pp, family = fam) + scale_fill_manual(values = cols, guide = "none") + xlim(-0.02, 1) + coord_cartesian(clip = "off") + theme_void() + theme(plot.margin = margin(0, 0, 0, 3))
lg <- data.frame(lab = c("\u2264 65 years", "> 65 years", "Female", "Male", "Alive", "Dead", "Stage I/II (I)", "Stage III/IV (II)", "Grade 1/2", "Grade 3/4"), fk = names(cols)[1:10]); lg$col <- rep(1:2, 5); lg$row <- rep(4:0, each = 2); lg$x <- c(0.02, 0.52)[lg$col]
pLg <- ggplot(lg) + geom_tile(aes(x, row, fill = fk), width = 0.05, height = 0.62) + geom_text(aes(x + 0.04, row, label = lab), hjust = 0, size = 4.8 / pp, family = fam) + scale_fill_manual(values = cols, guide = "none") + coord_cartesian(xlim = c(-0.01, 1), ylim = c(-0.5, 4.5), expand = FALSE) + theme_void() + theme(plot.margin = margin(0, 0, 0, 3))
## ---------- K: Reactome ----------
ro <- fread(file.path(r4, "K_reactome_ora.csv")); nm <- function(x) { y <- tolower(gsub("_", " ", sub("^REACTOME_", "", x))); y <- gsub("^g alpha i ", "G\u03b1i ", y); y <- gsub("^gpcr|^gpcr ", "GPCR ", y); y <- tools::toTitleCase(y); y <- gsub("^Gpcr", "GPCR", y); y <- gsub("Class [Aa] 1 Rhodopsin Like", "Class A/1 Rhodopsin-like", y); y <- gsub("Interactions Between a Lym.*", "Interactions", y); ifelse(nchar(y) > 46, paste0(substr(y, 1, 44), "\u2026"), y) }
ro <- ro[order(p.adjust)][, head(.SD, 4), by = direction]; ro[, `:=`(lab = nm(Description), lp = -log10(p.adjust))]; ro <- ro[order(-lp)]; ro[, y := rev(seq_len(.N)) * 1.0]; ro[, col := ifelse(direction == "Up in High", "#4C7FB8", "#E3B23C")]
ro[, txt2 := sprintf("%d DEGs, higher in %s-score tumors", Count, ifelse(direction == "Up in High", "high", "low"))]
pK <- ggplot(ro) + geom_rect(aes(xmin = 0, xmax = lp, ymin = y - 0.13, ymax = y + 0.13, fill = lp)) + scale_fill_gradient(low = "#DCE9F5", high = "#8FB6DD", guide = "none") + geom_text(aes(x = 0, y = y + 0.36, label = lab), hjust = 0, size = 5.2 / pp, family = fam, colour = "black") + geom_text(aes(x = 0, y = y - 0.33, label = txt2, colour = direction), hjust = 0, size = 4.6 / pp, family = fam) +
  scale_colour_manual(values = c("Up in High" = "#2E6DB0", "Up in Low" = "#B8860B"), guide = "none") + scale_y_continuous(expand = expansion(add = c(0.4, 0.3))) + labs(x = expression(-log[10](Pvalue)), y = "Reactome enrichment") + theme_pub() + theme(axis.text.y = element_blank(), axis.ticks.y = element_blank(), axis.line.y = element_blank())
## ---------- L: immune proxy boxplot ----------
isc <- fread(file.path(r4, "L_immune_proxy_scores.csv")); isc$group <- factor(isc$group, levels = c("Low", "High")); pw <- wilcox.test(`CD8 T effector` ~ group, isc)$p.value; yt <- max(isc$`CD8 T effector`) * 1.05
pL <- ggplot(isc, aes(group, `CD8 T effector`, colour = group)) + geom_jitter(width = 0.2, size = 0.55, alpha = 0.7) + geom_boxplot(aes(fill = group), notch = TRUE, width = 0.45, outlier.shape = NA, alpha = 0.25, linewidth = 0.3, colour = "grey25") + scale_colour_manual(values = c(Low = cLow, High = cHigh), guide = "none") + scale_fill_manual(values = c(Low = cLow, High = cHigh), guide = "none") +
  scale_x_discrete(labels = c("GIScore-low", "GIScore-high")) + annotate("text", x = 1.5, y = yt + 0.35, label = paste0("Wilcoxon, p = ", pfmt(pw)), size = 5 / pp, family = fam) + annotate("segment", x = 1, xend = 2, y = yt + 0.1, yend = yt + 0.1, linewidth = 0.25) + coord_cartesian(ylim = c(min(isc$`CD8 T effector`), yt + 0.5), clip = "off") + labs(x = NULL, y = "CD8 T-effector signature (z)") + theme_pub() + theme(panel.border = element_rect(fill = NA, linewidth = 0.25), axis.line = element_blank(), plot.margin = margin(8, 3, 2, 2))
## ---------- M: MDSC scatter with marginal histograms ----------
r_ <- fread(file.path(r4, "L_immune_proxies.csv"))[signature == "MDSC-like"]
pM0 <- ggplot(isc, aes(risk, `MDSC-like`)) + geom_point(size = 0.6, alpha = 0.7, colour = cHigh) + geom_smooth(method = "lm", formula = y ~ x, colour = cLow, fill = cLow, alpha = 0.3, linewidth = 0.5) + annotate("text", x = max(isc$risk), y = Inf, hjust = 1, vjust = 1.4, size = 4.8 / pp, family = fam, label = sprintf("p = %s\n\u03c1(Spearman) = %.2f", pfmt(r_$spearman_p), r_$spearman_rho)) + labs(x = "GIScore", y = "MDSC-like signature (z)") + theme_pub() + theme(panel.border = element_rect(fill = NA, linewidth = 0.25), axis.line = element_blank())
pM <- wrap_elements(full = ggMarginal(pM0, type = "histogram", bins = 25, xparams = list(fill = "#6CBF93", colour = "white", linewidth = 0.1), yparams = list(fill = "#E0605A", colour = "white", linewidth = 0.1)))
mtxt <- sprintf("p = %s, \u03c1(Spearman) = %.2f", pfmt(r_$spearman_p), r_$spearman_rho)
