row2 <- wrap_plots(pC, tg(pD, "D"), nrow = 1, widths = c(8.3, 3.7))
leftB <- wrap_plots(wrap_plots(tg(pE, "E"), tg(pF, "F"), tg(pG, "G"), nrow = 1), wrap_plots(tg(pK, "K"), tg(pL, "L"), tg(pM, "M"), nrow = 1, widths = c(1.15, 0.8, 1)), ncol = 1, heights = c(1.75, 2.45))
rightB <- wrap_plots(tg(pH, "H"), tg(pI, "I"), tg(pJ, "J"), pLg, ncol = 1, heights = c(1.25, 0.95, 0.85, 0.75))
bottom <- wrap_plots(leftB, rightB, nrow = 1, widths = c(8.6, 3.4))
comp <- wrap_plots(row1, row2, bottom, ncol = 1, heights = c(3.0, 1.85, 4.55)) & theme(text = element_text(family = fam), plot.tag = element_text(face = "bold", size = 10, family = fam), plot.tag.position = c(0, 1))
W <- 7.2; Hh <- 9.7
ggsave(file.path(out, "Figure4.svg"), comp, width = W, height = Hh, device = svglite::svglite)
ggsave(file.path(out, "Figure4.png"), comp, width = W, height = Hh, dpi = 400, device = ragg::agg_png)
ggsave(file.path(out, "Figure4.tiff"), comp, width = W, height = Hh, dpi = 600, device = ragg::agg_tiff, compression = "lzw")
cat("done; M annotation:", mtxt, "\n")
